import * as T from 'three'
import {asset} from './assets.js'
import {twoBoneKnee,orientLimb} from './ik.js'
import {bindElemental} from './elemental.js'
const UP=new T.Vector3(0,1,0)
// World-space planted feet. Only the lifted tetrapod may seek a new support.
export class Karakurt {
 constructor(items,model){ 
  this.root=new T.Group();this.body=new T.Group();this.root.add(this.body);this.position=this.root.position;this.normal=UP.clone();this.forward=new T.Vector3(0,0,-1);this.time=0;this.group=0;this.jump=0;this.velocity=0;this.cast=0;this.ready=false
  this.head=asset(items,'Carapace');this.body.add(this.head);this.abdomen=asset(items,'Abdomen');this.abdomen.position.set(0,0,.42);this.body.add(this.abdomen)
  for(let i=0;i<7;i++){const m=asset(items,'Marking');m.position.set((i%2?.08:-.08),.24,.3+i*.04);this.abdomen.add(m)}
  const eyes=new T.MeshStandardMaterial({color:0x1d0505,emissive:0x6d1717,emissiveIntensity:.6,roughness:.12})
  for(let i=0;i<8;i++){const e=new T.Mesh(new T.SphereGeometry(.025,8,6),eyes);e.position.set((i%4-1.5)*.065,.065+Math.floor(i/4)*.045,-.265);this.head.add(e)}
  this.legs=[];const geometry=new T.CylinderGeometry(1,.65,1,7),material=new T.MeshStandardMaterial({color:0x131820,roughness:.3,metalness:.15})
  for(const side of [-1,1])for(let i=0;i<4;i++){const upper=new T.Mesh(geometry,material),lower=new T.Mesh(geometry,material);this.root.add(upper,lower);this.legs.push({side,i,group:(i+(side>0?1:0))%2,upper,lower,foot:new T.Vector3(),start:new T.Vector3(),end:new T.Vector3(),phase:1,steps:0})}
  if(model){for(const child of [...this.body.children])child.visible=false;for(const l of this.legs){l.upper.visible=false;l.lower.visible=false}this.skin=bindElemental(this.body,model)}
 }
 reset(p,n=UP){this.position.copy(p);this.normal.copy(n);this.forward.set(0,0,-1);this.ready=false;this.lastPosition=p.clone();this.jump=0;this.velocity=0;this.cast=0;for(const l of this.legs)l.phase=1}
 leap(){if(this.jump<.001){this.velocity=3.4;return true}return false}
 turn(a){this.forward.applyAxisAngle(this.normal,a).normalize()}
 update(dt,moving,probe){
  const travel=this.lastPosition?this.position.clone().sub(this.lastPosition):new T.Vector3();travel.addScaledVector(this.normal,-travel.dot(this.normal));const speed=travel.length()/Math.max(dt,.001);const lead=travel.lengthSq()>1e-10?travel.normalize().multiplyScalar(Math.min(.10,speed*.04)):new T.Vector3();this.lastPosition=this.position.clone();
  this.time+=dt;this.cast=Math.max(0,this.cast-dt);this.velocity-=8*dt;this.jump=Math.max(0,this.jump+this.velocity*dt);if(!this.jump)this.velocity=0
  const basis=new T.Matrix4().makeBasis(this.forward.clone().cross(this.normal),this.normal,this.forward.clone().negate()),q=new T.Quaternion().setFromRotationMatrix(basis)
  this.body.quaternion.slerp(q,1-Math.exp(-dt*18));this.body.position.copy(this.normal).multiplyScalar(.31+this.jump+Math.sin(this.time*2)*.003)
  this.root.updateMatrixWorld(true)
  const right=this.forward.clone().cross(this.normal),bend=this.normal.clone().addScaledVector(right,.2)
  this.abdomen.rotation.x=T.MathUtils.lerp(this.abdomen.rotation.x,this.forward.y*.18+(this.normal.y<-.5?-.12:0)+Math.sin(this.cast*24)*Math.min(this.cast,.3),1-Math.exp(-dt*8))
  const active=this.legs.some(l=>l.phase<1)
  if(!active)this.group=1-this.group
  for(const l of this.legs){
   const home=this.position.clone().addScaledVector(right,l.side*(.65+(.1-Math.abs(l.i-1.5)*.06))).addScaledVector(this.forward,(1.5-l.i)*.38)
   const target=probe(home.clone().addScaledVector(this.normal,.65),this.normal.clone().negate(),1.5)||home
   if(!this.ready){l.foot.copy(target);l.end.copy(target)}
   if(l.phase>=1&&l.group===this.group&&l.foot.distanceTo(target)>.20&&this.jump<.05){l.start.copy(l.foot);l.end.copy(target).add(moving?lead:new T.Vector3());l.phase=0;l.steps++}
   if(l.phase<1){l.phase=Math.min(1,l.phase+dt*(moving?Math.min(13,5+speed*1.5):5));const t=l.phase*l.phase*(3-2*l.phase);l.foot.lerpVectors(l.start,l.end,t).addScaledVector(this.normal,Math.sin(Math.PI*l.phase)*.13)}
   const hip=this.position.clone().addScaledVector(this.normal,.31+this.jump).addScaledVector(right,l.side*.16).addScaledVector(this.forward,(1.5-l.i)*.12)
   let foot=l.foot.clone();if(this.jump>.03)foot=home.clone().addScaledVector(this.normal,this.jump*.7+.1)
   const delta=foot.clone().sub(hip);if(delta.length()>1.08)foot.copy(hip).add(delta.setLength(1.08))
   if(this.skin){
    const c=this.skin.chains.find(c=>c.side===l.side&&c.i===l.i);this.body.updateMatrixWorld(true)
    const origin=c.upper.getWorldPosition(new T.Vector3()),delta=foot.clone().sub(origin),reach=c.a+c.b-.002
    if(delta.length()>reach)foot.copy(origin).add(delta.setLength(reach))
    const knee=twoBoneKnee(origin,foot,c.a,c.b,bend.clone().addScaledVector(right,l.side*.8))
    this.skin.aim(c.upper,c.restUpper,knee.clone().sub(origin));this.skin.aim(c.lower,c.restLower,foot.clone().sub(knee));continue
   }
   const knee=twoBoneKnee(hip,foot,.55,.60,bend.clone().addScaledVector(right,l.side*.8))
   orientLimb(l.upper,hip.clone().sub(this.position),knee.clone().sub(this.position),.027);orientLimb(l.lower,knee.clone().sub(this.position),foot.clone().sub(this.position),.021)
  }
  if(this.skin)this.skin.flex(this.abdomen.rotation.x)
  this.ready=true
 }
}
